insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('poelee de legume', 'Poêlée de légumes', array['legume saute', 'poelee legume', 'legume a la poele', 'wok de legume']::text[], 'dish', $r$[{"title":"Poêlée de légumes","intro":"Des légumes de saison sautés à la poêle, encore croquants, avec de l'ail et des herbes.","minutes":25,"calories":150,"difficulty":"Facile","imageSearch":"sauteed vegetables","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":200,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"herbes de Provence","plural":"herbes de Provence","qty":1,"unit":"c. à c.","have":false}],"steps":[{"text":"Coupe tous les légumes en morceaux de même taille.","timer":null},{"text":"Fais revenir l'oignon et les carottes 5 min dans l'huile.","timer":{"label":"Poêle","min":5}},{"text":"Ajoute le poivron, la courgette et les champignons et laisse 10 min à feu vif.","timer":{"label":"Poêle","min":10}},{"text":"Assaisonne d'herbes de Provence, de sel et de poivre.","timer":null}],"variant":"La classique","change":""},{"title":"Wok de légumes","intro":"Une poêlée de légumes à l'asiatique, rapide et croquante.","minutes":20,"calories":160,"difficulty":"Facile","imageSearch":"vegetable stir fry","veg":true,"oven":false,"cold":false,"missing":"","origin":"Inspiration asiatique","serves":4,"items":[{"name":"brocoli","plural":"brocolis","qty":1,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"pois gourmands","plural":"pois gourmands","qty":150,"unit":"g","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false},{"name":"huile de sésame","plural":"huile de sésame","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Coupe les légumes en fines lamelles et le brocoli en petites fleurettes.","timer":null},{"text":"Fais sauter les carottes et le brocoli 4 min à feu très vif.","timer":{"label":"Poêle","min":4}},{"text":"Ajoute le poivron, les pois gourmands et le gingembre, et laisse 3 min.","timer":{"label":"Poêle","min":3}},{"text":"Arrose de sauce soja et d'huile de sésame.","timer":null}],"variant":"Au wok","change":"Sautés au wok avec sauce soja et gingembre."},{"title":"Poêlée de légumes aux œufs","intro":"Une poêlée complète, avec des œufs au plat dessus.","minutes":25,"calories":260,"difficulty":"Facile","imageSearch":"vegetable skillet eggs","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"tomate","plural":"tomates","qty":2,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais revenir l'oignon, le poivron et la courgette 10 min.","timer":{"label":"Poêle","min":10}},{"text":"Ajoute les tomates en dés et laisse 5 min.","timer":{"label":"Poêle","min":5}},{"text":"Creuse 4 puits et casse un œuf dans chacun.","timer":null},{"text":"Couvre et laisse cuire 5 min.","timer":{"label":"Poêle","min":5}}],"variant":"Avec des œufs","change":"Des œufs cuits au milieu des légumes."}]$r$::jsonb, 'claude')
