mmes de terre dorées à la poêle, avec de l'ail et du persil.","minutes":35,"calories":280,"difficulty":"Facile","imageSearch":"pan fried potatoes","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1000,"unit":"g","have":false},{"name":"huile","plural":"huile","qty":3,"unit":"c. à s.","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Épluche les pommes de terre et coupe-les en dés.","timer":null},{"text":"Fais-les dorer 25 min dans l'huile et le beurre à feu moyen, en remuant souvent.","timer":{"label":"Poêle","min":25}},{"text":"Ajoute l'ail et le persil hachés en fin de cuisson.","timer":null},{"text":"Sale et poivre.","timer":null}],"kids":true},{"title":"Salade de quinoa","intro":"Du quinoa avec concombre, tomates, feta et herbes, comme un taboulé.","minutes":25,"calories":380,"difficulty":"Facile","imageSearch":"quinoa salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"quinoa","plural":"quinoa","qty":200,"unit":"g","have":false},{"name":"concombre","plural":"concombres","qty":1,"unit":"","have":false},{"name":"tomate cerise","plural":"tomates cerises","qty":250,"unit":"g","have":false},{"name":"feta","plural":"fetas","qty":150,"unit":"g","have":false},{"name":"menthe fraîche","plural":"menthe fraîche","qty":null,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false}],"steps":[{"text":"Rince le quinoa, puis fais-le cuire 12 min à l'eau salée. Égoutte et laisse refroidir.","timer":{"label":"Cuisson","min":12}},{"text":"Coupe le concombre en dés et les tomate