","min":12}}],"kids":true},{"title":"Cake jambon olives","intro":"Le cake salé de l'apéro et des pique-niques, au jambon et aux olives.","minutes":60,"calories":320,"difficulty":"Facile","imageSearch":"savory ham olive loaf cake","veg":false,"oven":true,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":200,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"lait","plural":"laits","qty":10,"unit":"cl","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":10,"unit":"cl","have":false},{"name":"dés de jambon","plural":"dés de jambon","qty":150,"unit":"g","have":false},{"name":"olive verte","plural":"olives vertes","qty":100,"unit":"g","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":80,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":1,"unit":"c. à c.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Mélange la farine, la levure, les œufs, le lait et l'huile.","timer":null},{"text":"Ajoute le jambon, les olives coupées, l'emmental, sel et poivre.","timer":null},{"text":"Verse dans un moule à cake et enfourne 45 min.","timer":{"label":"Four","min":45}}],"kids":true},{"title":"Salade de pâtes","intro":"Des pâtes froides avec tomates cerises, mozzarella, jambon et basilic.","minutes":25,"calories":480,"difficulty":"Facile","imageSearch":"pasta salad","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"pâtes courtes","plural":"pâtes courtes","qty":300,"unit":"g","have":false},{"name":"tomate cerise","plural":"tomates cerises","qty":250,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarellas","qty":1,"unit":"","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":4,"unit":"tranches"